('day_start', '{"scenario":"mystery","payload_eq":{"day":2}}', '{"action":"story_event","actor":null,"payload":{"kind":"quarrel","text":"In the square, before seven villagers, Tobin Marsh accuses the mill helper of selling flour on the side. Someone had told him so."},"visibility":"public"}', NULL, 0),
