('day_start', '{"scenario":"mystery","payload_eq":{"day":2}}', '{"action":"story_event","actor":1,"payload":{"kind":"pocket_key","text":"At the well, Old Wick lifts a mill key from the hook and slips it into his pocket. Only a child on the wall sees.","target_actor":10},"visibility":"private"}', NULL, 0),
('day_start', '{"scenario":"mystery","payload_eq":{"day":3}}', '{"action":"story_event","actor":null,"payload":{"kind":"thorn_threat","text":"Garth Thorn shouts across the square that he will see Tobin''s mill burn before he pays those prices."},"visibility":"public"}', NULL, 0),
('day_start', '{"scenario":"mystery","payload_eq":{"day":3}}', '{"action":"discover","actor":11,"payload":{"clue":"C25"},"visibility":"private"}', NULL, 0),
('day_start', '{"scenario":"mystery","payload_eq":{"day":4}}', '{"action":"story_event","actor":null,"payload":{"kind":"fire","text":"At midnight the mill bell rings and does not stop. Tobin''s Mill burns."},"visibility":"public"}', NULL, 0),
('day_start', '{"scenario":"mystery","payload_eq":{"day":4}}', '{"action":"story_event","actor":null,"payload":{"kind":"tobin_dead","text":"Tobin Marsh lies dead in his own office. He died before the fire."},"visibility":"private"}', NULL, 0),
('day_start', '{"scenario":"mystery","payload_eq":{"day":5}}', '{"action":"story_event","actor":null,"payload":{"kind":"pike_arrives","text":"Sergeant Pike rides in at dawn under the Reeve''s colours, with a nervous young deputy called Corwen. He sets up a table in the inn and holds up a mill key found in the ashes. ''Whose is this?'' It is yours."},"visibility":"public"}', NULL, 0),
('day_start', '{"scenario":"mystery","payload_eq":{"day":5}}', '{"action":"story_enter","actor":null,"payload":{"entity_id":32,"state":{"mood":"content","trust":50,"coins":15}},"visibility":"private"}', NULL, 0),
('day_start', '{"scenario":"mystery","payload_eq":{"day":5}}', '{"action":"story_enter","actor":null,"payload":{"entity_id":33,"state":{"mood":"curious","trust":50,"coins":5}},"visibility":"private"}', NULL, 0),
('day_start', '{"scenario":"mystery","payload_eq":{"day":5}}', '{"action":"state_change","actor":null,"payload":{"entity_id":11,"add":{"suspicion":15}},"visibility":"private"}', NULL, 0),
('day_start', '{"scenario":"mystery","payload_eq":{"day":5}}', '{"action":"discover","actor":11,"payload":{"clue":"C12"},"visibility":"private"}', NULL, 0),
('day_start', '{"scenario":"mystery","payload_eq":{"day":6}}', '{"action":"story_event","actor":null,"payload":{"kind":"wick_attacked","text":"Overnight a stone smashed the well-house window. Old Wick appears at the well at noon with a bandage round his head and a brave smile. ''Somebody wants me quiet,'' he says. ''I cannot think why.''"},"visibility":"public"}', NULL, 0),
('day_start', '{"scenario":"mystery","payload_eq":{"day":6}}', '{"action":"story_event","actor":null,"payload":{"kind":"mob","text":"Garth Thorn''s men gather outside Ines''s inn and demand she answer for Tobin''s debts. The lantern over the door shakes in the wind."},"visibility":"public"}', NULL, 0),
('day_start', '{"scenario":"mystery","payload_eq":{"day":7}}', '{"action":"story_event","actor":1,"payload":{"kind":"wick_plan","text":"Old Wick sits very still at the well and counts who in Alderbrook knows too much."},"visibility":"private"}', NULL, 0),
